#!/usr/bin/env node
/**
 * One source of truth for this repo's plugin list: `plugins.json`.
 *
 *   node scripts/plugins.mjs index                  regenerate market/index.json, market/icons/ and the README blocks
 *   node scripts/plugins.mjs index --commit <sha>   repin to another commit (rewrites plugins.json)
 *   node scripts/plugins.mjs check                  fail when the generated files drift from plugins.json
 *   node scripts/plugins.mjs specs [--local]        print one install spec per plugin
 *   node scripts/plugins.mjs install [--remote]     install this checkout (link:, default) or the pinned commit
 *
 * Zero dependencies, Node 22+.
 */

import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { copyFile, mkdir, readFile, writeFile } from 'node:fs/promises';
import { delimiter, dirname, extname, join, resolve, sep } from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const BLOCKS = ['plugins:table', 'plugins:specs', 'plugins:install'];

/* ---------------------------------------------------------------- manifest */

/**
 * Resolve what each entry actually installs. Repo entries take their name and
 * version from the plugin's own package.json, so a plugin's identity lives in
 * exactly one place; npm entries carry the exact version this repo tested with.
 * @param {object} manifest parsed plugins.json
 * @param {(dir: string) => object} readPackage reads a plugin's package.json
 * @returns {object} the manifest with every plugin resolved
 */
export function normalizeManifest(manifest, readPackage) {
  if (typeof manifest.profile !== 'string' || manifest.profile === '') throw new Error('plugins.json: profile 缺失');
  if (typeof manifest.repository !== 'string' || !/^https:\/\//.test(manifest.repository)) throw new Error('plugins.json: repository 必须是 https 地址');
  if (typeof manifest.commit !== 'string' || !/^[0-9a-f]{40}$/.test(manifest.commit)) throw new Error('plugins.json: commit 必须是 40 位小写 sha');
  const categories = new Set(Object.keys(manifest.market?.categories ?? {}));
  const seen = new Set();
  const plugins = (manifest.plugins ?? []).map((plugin) => {
    let resolved;
    if (plugin.source === 'npm') {
      if (typeof plugin.package !== 'string' || plugin.package === '') throw new Error('plugins.json: npm 条目需要 package');
      if (plugin.tag !== undefined && (typeof plugin.tag !== 'string' || plugin.tag === '')) throw new Error(`${plugin.package}: tag 必须是非空字符串`);
      if (typeof plugin.version !== 'string' || !/^\d+\.\d+\.\d+/.test(plugin.version)) {
        const hint = plugin.tag === undefined ? '需要确切 version' : `还没有解析过 ${plugin.tag}，先运行 node scripts/plugins.mjs index --refresh`;
        throw new Error(`${plugin.package}: ${hint}`);
      }
      if (!Number.isInteger(plugin.publishTimestamp)) throw new Error(`${plugin.package}: 需要 publishTimestamp（秒）`);
      resolved = { ...plugin, name: plugin.package };
    } else if (plugin.source === 'repo') {
      if (typeof plugin.dir !== 'string' || plugin.dir === '') throw new Error('plugins.json: repo 条目需要 dir');
      let pkg;
      try {
        pkg = readPackage(plugin.dir);
      } catch {
        throw new Error(`${plugin.dir}: 读不到 package.json`);
      }
      if (pkg.dsh?.bundle?.patch === undefined) throw new Error(`${plugin.dir}/package.json 没有 dsh.bundle.patch，不是 DSH 组合包`);
      resolved = { ...plugin, name: pkg.name, version: pkg.version, icon: plugin.icon ?? 'icon.svg' };
    } else {
      throw new Error(`plugins.json: 未知 source ${JSON.stringify(plugin.source)}`);
    }
    if (!categories.has(resolved.category)) throw new Error(`${resolved.name}: category ${JSON.stringify(resolved.category)} 未在 market.categories 声明`);
    if (seen.has(resolved.name)) throw new Error(`${resolved.name}: 包名重复`);
    seen.add(resolved.name);
    return resolved;
  });
  if (plugins.length === 0) throw new Error('plugins.json: plugins 为空');
  return { ...manifest, plugins };
}

export function gitUrl(repository) {
  return repository.endsWith('.git') ? repository : `${repository}.git`;
}

/**
 * The spec that installs one plugin.
 * @param {object} plugin resolved entry
 * @param {{ mode: 'remote' | 'local', commit: string, repository: string, root: string }} context
 */
export function specOf(plugin, { mode, commit, repository, root }) {
  if (plugin.source === 'npm') return `${plugin.name}@${plugin.version}`;
  if (mode === 'local') return `link:${join(root, plugin.dir).split(sep).join('/')}`;
  return `git+${gitUrl(repository)}#${commit}&path:/${plugin.dir}`;
}

export function specsOf(manifest, context) {
  return manifest.plugins.map((plugin) => specOf(plugin, context));
}

/* --------------------------------------------------------------- rendering */

export function renderIndex(manifest, { commit, times }) {
  return {
    $comment: 'Generated by `node scripts/plugins.mjs index` from plugins.json. Do not edit by hand.',
    format: 1,
    title: manifest.market.title,
    description: manifest.market.description,
    metadata: { categories: manifest.market.categories },
    plugins: manifest.plugins.map((plugin) => {
      const engines = plugin.source === 'repo' ? manifest.engines : plugin.engines;
      const version = {
        version: plugin.version,
        publishTimestamp: plugin.source === 'repo' ? times[plugin.dir] : plugin.publishTimestamp,
        source: plugin.source === 'repo'
          ? { type: 'git', url: gitUrl(manifest.repository), commit, path: plugin.dir }
          : { type: 'npm' }
      };
      if (engines !== undefined) version.engines = engines;
      const entry = { name: plugin.name, title: plugin.title, description: plugin.summary };
      if (plugin.author !== undefined) entry.author = plugin.author;
      if (plugin.homepage !== undefined) entry.homepage = plugin.homepage;
      if (plugin.source === 'repo') entry.icon = `./icons/${plugin.dir}${extname(plugin.icon)}`;
      entry.metadata = { category: plugin.category, ...(plugin.keywords === undefined ? {} : { keywords: plugin.keywords }) };
      entry.versions = [version];
      return entry;
    })
  };
}

const labelOf = (plugin) => plugin.title.zh ?? plugin.title.en;
const summaryOf = (plugin) => plugin.summary.zh ?? plugin.summary.en;

export function renderTable(manifest) {
  const rows = manifest.plugins.map((plugin) => {
    const target = plugin.source === 'repo' ? `${plugin.dir}/README.md` : plugin.homepage;
    const origin = plugin.source === 'repo' ? '本仓库' : 'npm';
    return `| [${labelOf(plugin)}](${target}) | ${summaryOf(plugin)} | ${plugin.version} | ${origin} |`;
  });
  return ['| 插件 | 功能 | 版本 | 来源 |', '|---|---|---|---|', ...rows].join('\n');
}

export function renderSpecs(manifest, context) {
  return manifest.plugins.map((plugin) => `- ${labelOf(plugin)}：\`${specOf(plugin, context)}\``).join('\n');
}

export function renderInstall(manifest, context) {
  const specs = specsOf(manifest, context).map((spec) => `"${spec}"`);
  const command = ['dsh', 'plugin', '--profile', manifest.profile, 'add', '--ignore-scripts', ...specs].join(' ');
  return ['```bash', command, '```'].join('\n');
}

/**
 * Replace the body between `<!-- <name>:start -->` and `<!-- <name>:end -->`.
 * @param {string} text file contents
 * @param {string} name block name
 * @param {string} body new body, without the markers
 */
export function replaceBlock(text, name, body, file = 'README.md') {
  const start = `<!-- ${name}:start -->`;
  const end = `<!-- ${name}:end -->`;
  const from = text.indexOf(start);
  const to = text.indexOf(end);
  if (from < 0 || to < from) throw new Error(`${file}: 缺少 ${start} / ${end} 标记`);
  return `${text.slice(0, from + start.length)}\n${body.trimEnd()}\n${text.slice(to)}`;
}

export function renderReadme(text, manifest, context) {
  const bodies = {
    'plugins:table': renderTable(manifest),
    'plugins:specs': renderSpecs(manifest, context),
    'plugins:install': renderInstall(manifest, context)
  };
  return BLOCKS.reduce((current, name) => replaceBlock(current, name, bodies[name]), text);
}

/* ------------------------------------------------------------------- files */

async function readJson(file) {
  return JSON.parse(await readFile(file, 'utf8'));
}

// The index stores LF; a Windows checkout rewrites it to CRLF, so compare and
// rewrite in LF regardless of core.autocrlf.
const normalizeEol = (text) => text.replaceAll('\r\n', '\n');

const packageReader = (root) => (dir) => JSON.parse(readFileSync(join(root, dir, 'package.json'), 'utf8'));

export async function loadManifest(root = ROOT) {
  return normalizeManifest(await readJson(join(root, 'plugins.json')), packageReader(root));
}

/** Generate the files that must stay in step with plugins.json. */
export async function generated(root, manifest, context) {
  const times = {};
  for (const plugin of manifest.plugins.filter((entry) => entry.source === 'repo')) {
    ensureInCommit(root, context.commit, plugin.dir);
    times[plugin.dir] = Number(git(root, ['log', '-1', '--format=%ct', context.commit, '--', plugin.dir]).trim());
  }
  const index = renderIndex(manifest, { commit: context.commit, times });
  const readme = renderReadme(normalizeEol(await readFile(join(root, 'README.md'), 'utf8')), manifest, { ...context, root, repository: manifest.repository });
  const icons = manifest.plugins
    .filter((plugin) => plugin.source === 'repo')
    .map((plugin) => ({
      from: join(root, plugin.dir, plugin.icon),
      to: join(root, 'market', 'icons', `${plugin.dir}${extname(plugin.icon)}`)
    }));
  return {
    files: {
      'market/index.json': `${JSON.stringify(index, null, 2)}\n`,
      'README.md': readme
    },
    icons
  };
}

/* --------------------------------------------------------------------- git */

function git(root, args) {
  const result = spawnSync('git', args, { cwd: root, encoding: 'utf8' });
  if (result.status !== 0) throw new Error(`git ${args.join(' ')} 失败: ${result.stderr.trim()}`);
  return result.stdout;
}

function dirtyPaths(root, manifest) {
  const dirs = manifest.plugins.filter((plugin) => plugin.source === 'repo').map((plugin) => plugin.dir);
  return git(root, ['status', '--porcelain', '--', ...dirs]).trim();
}

// A pin is only useful when the commit it names really contains the plugin:
// `git+…&path:/<dir>` installs nothing from a commit that predates the directory.
function ensureInCommit(root, commit, dir) {
  const result = spawnSync('git', ['cat-file', '-e', `${commit}:${dir}/package.json`], { cwd: root });
  if (result.status !== 0) throw new Error(`提交 ${commit} 里没有 ${dir}/package.json，先提交插件源码再重新 pin`);
}

/* ------------------------------------------------------------------ registry */

/**
 * Resolve a dist-tag to the exact version and publish time this repo records.
 * Resolved at generation time so installs, the market index and `check` all stay
 * exact and offline.
 * @param {string} packageName npm package name
 * @param {string} tag dist-tag such as `latest`
 * @param {{ registry?: string, fetchImpl?: typeof fetch }} options
 * @returns {Promise<{ version: string, publishTimestamp: number }>}
 */
export async function resolveTag(packageName, tag, { registry = 'https://registry.npmjs.org', fetchImpl = fetch } = {}) {
  const url = `${registry.replace(/\/+$/, '')}/${encodeURIComponent(packageName)}`;
  const response = await fetchImpl(url, { headers: { accept: 'application/json' } });
  if (!response.ok) throw new Error(`查询 ${packageName} 失败: HTTP ${response.status}`);
  const document = await response.json();
  const version = document['dist-tags']?.[tag];
  if (typeof version !== 'string') throw new Error(`${packageName} 没有 dist-tag ${tag}`);
  const published = document.time?.[version];
  if (typeof published !== 'string') throw new Error(`${packageName}@${version} 缺少发布时间`);
  return { version, publishTimestamp: Math.floor(Date.parse(published) / 1000) };
}

async function refreshTags(raw, registry) {
  for (const entry of raw.plugins.filter((plugin) => plugin.source === 'npm' && typeof plugin.tag === 'string')) {
    const { version, publishTimestamp } = await resolveTag(entry.package, entry.tag, { registry });
    if (entry.version !== version) console.log(`${entry.package}: ${entry.version ?? '未解析'} -> ${version} (${entry.tag})`);
    entry.version = version;
    entry.publishTimestamp = publishTimestamp;
  }
}

/* ----------------------------------------------------------------- commands */

async function index(root, args) {
  const raw = await readJson(join(root, 'plugins.json'));
  const next = structuredClone(raw);
  let commit = next.commit;
  if (args.commit !== undefined) {
    if (!/^[0-9a-f]{40}$/.test(args.commit)) throw new Error('--commit 需要 40 位小写 sha');
    const dirty = dirtyPaths(root, normalizeManifest(next, packageReader(root)));
    if (dirty !== '' && args['allow-dirty'] !== true) throw new Error(`插件源码有未提交改动，先提交再 pin：\n${dirty}`);
    commit = args.commit;
  }
  if (args.refresh === true) await refreshTags(next, args.registry);
  // Generate before writing anything, so a pin or a refresh that cannot install leaves the repo unchanged.
  const manifest = normalizeManifest({ ...next, commit }, packageReader(root));
  const { files, icons } = await generated(root, manifest, { commit, root });
  const serialized = `${JSON.stringify({ ...next, commit }, null, 2)}\n`;
  if (serialized !== `${JSON.stringify({ ...raw, commit: raw.commit }, null, 2)}\n`) {
    await writeFile(join(root, 'plugins.json'), serialized);
    console.log('updated plugins.json');
  }
  for (const [file, content] of Object.entries(files)) {
    await writeFile(join(root, file), content);
    console.log(`wrote ${file}`);
  }
  await mkdir(join(root, 'market', 'icons'), { recursive: true });
  for (const icon of icons) {
    await copyFile(icon.from, icon.to);
    console.log(`copied ${icon.to.slice(root.length + 1)}`);
  }
}

async function check(root) {
  const manifest = await loadManifest(root);
  const { files } = await generated(root, manifest, { commit: manifest.commit, root });
  const stale = [];
  for (const [file, expected] of Object.entries(files)) {
    if (normalizeEol(await readFile(join(root, file), 'utf8')) !== expected) stale.push(file);
  }
  if (stale.length > 0) {
    console.error(`生成物与 plugins.json 不一致：${stale.join(', ')}\n运行 node scripts/plugins.mjs index`);
    process.exitCode = 1;
    return;
  }
  console.log('生成物与 plugins.json 一致');
}

function findCli() {
  const names = process.platform === 'win32' ? ['dsh.cmd', 'dsh.exe', 'dsh'] : ['dsh'];
  for (const directory of (process.env.PATH ?? '').split(delimiter)) {
    if (directory === '') continue;
    for (const name of names) {
      const candidate = join(directory, name);
      if (existsSync(candidate)) return candidate;
    }
  }
  if (process.platform === 'win32') {
    for (const base of [join(process.env.LOCALAPPDATA ?? '', 'Programs', 'DeepSeek Harness'), join(process.env.ProgramFiles ?? '', 'DeepSeek Harness')]) {
      const candidate = join(base, 'resources', 'runtime', 'cli', 'bin', 'dsh.cmd');
      if (existsSync(candidate)) return candidate;
    }
  }
  throw new Error('找不到 dsh CLI：用 --dsh 指定，或设置 DSH_CLI 环境变量');
}

function assertShellSafe(specs) {
  const forbidden = process.platform === 'win32' ? /["%]/ : /["`$\\]/;
  for (const spec of specs) {
    if (forbidden.test(spec)) throw new Error(`路径或 spec 含 shell 特殊字符，无法安全转义：${spec}`);
  }
}

async function install(root, args) {
  const manifest = await loadManifest(root);
  const mode = args.remote === true ? 'remote' : 'local';
  const specs = specsOf(manifest, { mode, commit: manifest.commit, repository: manifest.repository, root });
  assertShellSafe(specs);
  const cli = resolveCli(args);
  const profile = args.profile ?? manifest.profile;
  const command = [`"${cli}"`, 'plugin', '--profile', `"${profile}"`, 'add', '--ignore-scripts', ...specs.map((spec) => `"${spec}"`)].join(' ');
  console.log(command);
  if (args['dry-run'] === true) return;
  const result = spawnSync(command, { shell: true, stdio: 'inherit', cwd: root });
  process.exitCode = result.status ?? 1;
}

function resolveCli(args) {
  const explicit = args.dsh ?? process.env.DSH_CLI;
  if (explicit !== undefined) return explicit;
  try {
    return findCli();
  } catch (error) {
    if (args['dry-run'] !== true) throw error;
    console.error('（没找到 dsh CLI，下面的命令按 PATH 上的 dsh 打印）');
    return 'dsh';
  }
}

async function specs(root, args) {
  const manifest = await loadManifest(root);
  const mode = args.local === true ? 'local' : 'remote';
  for (const spec of specsOf(manifest, { mode, commit: manifest.commit, repository: manifest.repository, root })) console.log(spec);
}

function parseArgs(argv) {
  const args = { _: [] };
  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    if (!token.startsWith('--')) {
      args._.push(token);
      continue;
    }
    const [key, value] = token.slice(2).split('=');
    if (value !== undefined) args[key] = value;
    else if (argv[index + 1] !== undefined && !argv[index + 1].startsWith('--')) args[key] = argv[++index];
    else args[key] = true;
  }
  return args;
}

const COMMANDS = { index, check, install, specs };

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const command = COMMANDS[args._[0]];
  if (command === undefined) throw new Error('用法: node scripts/plugins.mjs <index|check|specs|install> [选项]');
  await command(ROOT, args);
}

if (process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error.message);
    process.exitCode = 1;
  });
}
